Lemma opt_valid_from_fuel : forall f f' nc s, (length s < f)%nat -> (length s < f')%nat ->
  opt_valid_from f nc s = opt_valid_from f' nc s.
Proof.
  induction f as [|f IH]; intros f' nc s Hf Hf'; [lia|].
  destruct f' as [|f']; [lia|]. cbn.
  destruct (tok_next nc s) as [| |k l] eqn:R; try reflexivity.
  pose proof (tok_next_tok_bound _ _ _ _ R) as [B L].
  apply IH; rewrite length_skipn; lia.
Qed.

Lemma toks_from_fuel : forall f f' nc s, (length s < f)%nat -> (length s < f')%nat ->
  toks_from f nc s = toks_from f' nc s.
Proof.
  induction f as [|f IH]; intros f' nc s Hf Hf'; [lia|].
  destruct f' as [|f']; [lia|]. cbn.
  destruct (tok_next nc s) as [| |k l] eqn:R; try reflexivity.
  pose proof (tok_next_tok_bound _ _ _ _ R) as [B L].
  f_equal. apply IH; rewrite length_skipn; lia.
Qed.

Lemma skipn_skipn' : forall {X} (a b : nat) (l : list X), skipn a (skipn b l) = skipn (b + a) l.
Proof. intros X a b l. rewrite skipn_skipn. f_equal. lia. Qed.

