Definition vl_ctx (m m1 : mem) (sp s0v s1v rav : word) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z)
    (obj : list cell) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -64) obj
  /\ rw_cells rsegs m1 (bv_unsigned sp + -24) [C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells rsegs m1 LST (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at rsegs m1 SP sbs
  /\ stk rsegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition vl_pure (sp : word) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ lo + 64 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ (bv_unsigned sp <= LST \/ LST + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo).

Local Ltac open_vctx CTX PURE :=
  lazymatch type of CTX with vl_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (OBJ & FRhi & LSV & WIN & ST & MU & WM & MI);
  destruct PURE as (SP64 & LO & L94 & SEPL & SEPW);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ LSV) as LB; cbn [cells_size csize Nat.add length] in LB, SEPL;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold OptItCells in * end.
