Local Ltac call_optit A lst it vp vl err SP pad7 sbs lrest :=
  let S := fresh "OS" in
  pose proof optit_incr_spec as S;
  unfold optit_incr_stmt, optit_incr_post, SZ_TOKIT, P_OPT_TOKEN_LIST_INCR in S;
  call (S A lst it vp vl err SP pad7 sbs lrest).

Lemma tok_suffix_off : forall SP i sbs, 0 <= SP -> tok_suffix SP (SP + Z.of_nat i) sbs = skipn i (zbytes sbs).
Proof. intros SP i sbs H. unfold tok_suffix. rewrite zbytes_skipn. f_equal. lia. Qed.

Local Ltac nrmw := nrm; unfold wz.

Local Ltac vl_rebuild_ctx m sp :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | OBJ : rw_cells _ mx (bv_unsigned sp + -64) ?ob, FRhi : rw_cells _ mx (bv_unsigned sp + -24) [C8 ?s1v; C8 ?s0v; C8 ?rav],
    LSV : rw_cells _ mx ?LST (C8 _ :: C8 _ :: ?lrest), WIN : bytes_at _ mx ?SP ?sbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : vl_ctx m mx sp s0v s1v rav LST SP sbs lrest lo ob)
        by (split; [exact OBJ | split; [exact FRhi | split; [exact LSV | split; [exact WIN | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]]])
  end end.

(* [comment removed for export] *)
Local Ltac vl_call_incr sp LST it vp vl err SP pad7 sbs lrest :=
  call_optit (bv_unsigned sp + -64) LST it vp vl err SP pad7 sbs lrest;
  [ assumption | assumption | assumption | lia | lia | lia | cbn [cells_size csize Nat.add length]; lia | assumption | ];
  try match goal with H : rw_cells _ _ LST _, H' : rw_cells _ _ LST _ |- _ => clear H' end;
  try match goal with H : bytes_at _ _ SP _, H' : bytes_at _ _ SP _ |- _ => clear H' end;
  lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + -64) _ |- _ => rename H into OBJ end;
  lazymatch goal with H : rw_cells _ _ LST _ |- _ => try rename H into LSV end;
  lazymatch goal with H : bytes_at _ _ SP _ |- _ => try rename H into WIN end.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__4 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.Ref.XP_tok_stmt.tokres Sort Prop.

(* [comment removed for export] *)
Lemma vl_loop : forall (k i : nat) rax a0x a1x ra sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z)
    (vp vl : Z) (pad7 : list byte),
  (length sbs - i <= k)%nat -> (0 < i <= length sbs)%nat ->
  vl_ctx m m1 sp s0v s1v ra LST SP sbs lrest lo (OptItCells LST (SP + Z.of_nat i) vp vl 0 pad7) -> vl_pure sp LST SP sbs lrest lo ->
  evt rsegs (vl_post_v (opt_valid_from (S (length sbs - i)) true (skipn i (zbytes sbs)))
               ra sp gp tp s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz LST) (wz 1) a0x a1x a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
